<div class="row">
    <div class="col-md-3">
        <div class="form-group">
            <label>Single Day Rate</label>
            <input type="number" name="single_day_rate" class="form-control" required>
        </div>
    </div>
    <div class="col-md-3">
        <div class="form-group">
            <label>Full Week Rate</label>
            <input type="number" name="full_week_rate" class="form-control" required>
        </div>
    </div>
    <div class="col-md-3">
        <div class="form-group">
            <label>Full Month Rate</label>
            <input type="number" name="full_month_rate" class="form-control" required>
        </div>
    </div>
    <div class="col-md-3">
        <div class="form-group">
            <label>Status</label>
            <div class="form-check mt-2">
                <input type="checkbox" name="is_active" class="form-check-input" id="is_active" value="1" checked>
                <label class="form-check-label" for="is_active">Active</label>
            </div>
        </div>
    </div>
</div>